// <auto-generated/>

namespace Fanex.CustomerSetting.Module.SearchCopy.Services
{
    using Core.Models;
    using Criteria;
    using Entities;
    using Fanex.CustomerSetting.Module.Core.Criteria;
    using Fanex.CustomerSetting.Module.Core.Services.Impl;
    using Fanex.CustomerSetting.Module.Core.Services.Interface;
    using Fanex.Data;
    using Fanex.Tarus.Infrastructure.Extensions;
    using Repositories;
    using System;
    using System.Collections;
    using System.Collections.Generic;
    using System.Linq;
    using System.Threading;
    using static Sunplus.Accounting.Core.Common.Enumerations;

    internal class SearchCopyService : ISearchCopyService
    {
        private readonly ISearchCopyRepository _searchCopyRepository;

        private readonly IServiceBase _serviceBase;

        public SearchCopyService(ISearchCopyRepository searchCopyRepository = null, IServiceBase serviceBase = null)
        {
            _searchCopyRepository = searchCopyRepository ?? new SearchCopyRepository();
            _serviceBase = serviceBase ?? new ServiceBase();
        }

        public SearchResult SearchExistingCustomer(string username, bool isMember)
        {
            var smaCustomers = _searchCopyRepository
                .GetSMACustomerInfo(new SearchExistingCustomerCriteria(username, ObjectDbExtensions.GetSiteDBConfigByUsername(username).CustDBGroupID))
                .Where(smap => smap.CustId != 0);

            var searchResult = isMember
                ? BuildMemberSearchResult(username, smaCustomers)
                : BuildSuperSearchResult(username, smaCustomers);

            if (searchResult.CustId > 0)
            {
                var enableResult = _searchCopyRepository.ExecuteNonQuery(
                    new CheckCustomerEnabledCriteria(username));

                if (enableResult.IsSuccess)
                {
                    return searchResult;
                }
            }

            return new SearchResult();
        }

        private static SearchResult BuildSuperSearchResult(
            string username,
            IEnumerable<SMACustomerInfo> smaCustomers)
        {
            var super = smaCustomers.FirstOrDefault(smap =>
                smap.Username.Equals(username, StringComparison.OrdinalIgnoreCase)
                && smap.RoleId == 4);

            return super == null
                ? new SearchResult()
                : new SearchResult(super.CustId, 0, null);
        }

        private static SearchResult BuildMemberSearchResult(
            string username,
            IEnumerable<SMACustomerInfo> smaCustomers)
        {
            var smaCustomerList = smaCustomers.ToList();

            if (smaCustomerList.Count == 4)
            {
                var member = smaCustomerList[0];
                var agent = smaCustomerList[1];
                var master = smaCustomerList[2];
                var super = smaCustomerList[3];

                if (username.Equals(member.Username, StringComparison.OrdinalIgnoreCase))
                {
                    return new SearchResult(
                        member.CustId,
                        agent.CustId,
                        $"{super.Username} > {master.Username} > {agent.Username}");
                }
            }

            return new SearchResult();
        }


        public CustomerInfo GetCustomerInfoByUserId(int custId, bool isMember, byte settingStatus)
        {
            var customerInfo = _searchCopyRepository.GetCustomerInfoByUserId(
                new GetCustomerInfoByUserIdCriteria(custId, isMember));
            return customerInfo;
        }

        public IEnumerable<Site> GetSitesExistingSuper(int userId)
        {
            var listSiteDTO = new List<Site>();
            var sites = _searchCopyRepository.GetSitesExistingSuper(new GetSitesCriteria(userId));
            sites
            .GroupBy(p => p.SiteLabel)
           .ToList()
           .ForEach(grp =>
           {
               if (string.IsNullOrEmpty(grp.Key))
               {
                   listSiteDTO.AddRange(grp.Select(pt => new Site(pt.SiteId.ToString(), pt.SiteName)));
               }
               else
               {
                   listSiteDTO.Add(new Site(grp.Key, grp.Key, null, grp.Select(p => new Site(p.SiteId.ToString(), p.SiteName))));
               }
           });

            return listSiteDTO;
        }


        public string CheckAvailableUsernames(string usernames)
        {
            var criteria = new GetExistingUsernameCriteria(usernames);
            var existingUsernames = _searchCopyRepository
                .GetExistingUsernames(criteria)
                .ToList();

            return existingUsernames.Count == 0
                ? string.Empty
                : $"Unavailable username(s): {string.Join(", ", existingUsernames)}";
        }
    }
}
